// Local state of the plugin: ~/.openclaw/model-access/ (override with MODEL_ACCESS_HOME).
//   wallet.key   EVM private key that pays (0600; generated by `setup` when none is configured)
//   proxy.token  random token OpenClaw sends to the local proxy (blocks other local apps and web pages)
//   spend.json   what the proxy has paid: today, total, number of calls
import {existsSync,mkdirSync,readFileSync,writeFileSync,chmodSync,renameSync} from "node:fs";
import {homedir} from "node:os";
import {join} from "node:path";
import {randomBytes} from "node:crypto";

export const PLUGIN_ID="openclaw-model-access";
export const PROVIDER_ID="model-access";
export const DEFAULT_PORT=8423;
export const DEFAULT_GATEWAY="https://agent402-arb.rosariovitale0096.workers.dev";
// The gateway's receiving wallet. A 402 that asks to pay any other address is refused (nothing is signed).
export const DEFAULT_PAY_TO="0xf7eaf699C6E55887184809c57d597a64aB86d493";
export const DEFAULT_MAX_PER_CALL_USD=0.5;
export const DEFAULT_MAX_PER_DAY_USD=5;

export const stateDir=()=>process.env.MODEL_ACCESS_HOME||join(process.env.OPENCLAW_HOME||join(homedir(),".openclaw"),"model-access");
export const walletFile=()=>join(stateDir(),"wallet.key");
export const tokenFile=()=>join(stateDir(),"proxy.token");
export const spendFile=()=>join(stateDir(),"spend.json");
export const openclawConfigFile=()=>join(process.env.OPENCLAW_HOME||join(homedir(),".openclaw"),"openclaw.json");

const KEY_RE=/^0x[0-9a-fA-F]{64}$/;
function ensureDir(){mkdirSync(stateDir(),{recursive:true,mode:0o700});}
function writePrivate(file,text,{exclusive=false}={}){
 ensureDir();
 writeFileSync(file,text,{mode:0o600,flag:exclusive?"wx":"w"});
 try{chmodSync(file,0o600);}catch{}
}

// Wallet key precedence: plugin config > MODEL_ACCESS_WALLET_KEY > wallet.key. Only 0x + 64 hex counts.
// The env key is read once and removed from process.env so tools started by the agent never inherit it.
let envKey=null;
function takeEnvKey(){
 if(process.env.MODEL_ACCESS_WALLET_KEY!==undefined){envKey=process.env.MODEL_ACCESS_WALLET_KEY.trim();delete process.env.MODEL_ACCESS_WALLET_KEY;}
 return envKey||"";
}
export function resolveWalletKey(cfg={}){
 const c=[typeof cfg.walletKey==="string"?cfg.walletKey.trim():"",takeEnvKey()];
 try{if(existsSync(walletFile()))c.push(readFileSync(walletFile(),"utf8").trim());}catch{}
 return c.find(k=>KEY_RE.test(k))||null;
}
// Creates wallet.key only if it does not exist yet (never overwrites a key: it may hold funds).
export async function generateWallet(){
 const {generatePrivateKey,privateKeyToAccount}=await import("viem/accounts");
 if(existsSync(walletFile())){
  const pk=readFileSync(walletFile(),"utf8").trim();
  if(!KEY_RE.test(pk))throw Error(walletFile()+" exists but is not a valid key: fix or move it by hand");
  return {address:privateKeyToAccount(pk).address,created:false};
 }
 const pk=generatePrivateKey();
 writePrivate(walletFile(),pk+"\n",{exclusive:true});
 return {address:privateKeyToAccount(pk).address,created:true};
}
export function proxyToken({create=true}={}){
 try{if(existsSync(tokenFile())){const t=readFileSync(tokenFile(),"utf8").trim();if(/^[a-f0-9]{48}$/.test(t))return t;}}catch{}
 if(!create)return null;
 const t=randomBytes(24).toString("hex");
 writePrivate(tokenFile(),t+"\n");
 return t;
}

// ---- spend ledger (micro-USDC) ----
const today=()=>new Date().toISOString().slice(0,10);
export function readSpend(){
 let s={day:today(),dayMicro:"0",totalMicro:"0",calls:0};
 try{if(existsSync(spendFile()))s={...s,...JSON.parse(readFileSync(spendFile(),"utf8"))};}catch{}
 if(s.day!==today()){s.day=today();s.dayMicro="0";}
 return s;
}
// One proxy per machine writes this file (the port is unique); concurrent calls inside it are synchronous here.
function writeSpend(s){
 const tmp=spendFile()+"."+process.pid+".tmp";
 writePrivate(tmp,JSON.stringify(s,null,1)+"\n");
 renameSync(tmp,spendFile());
 return s;
}
export function addSpend(micro){
 const s=readSpend();
 s.dayMicro=String(BigInt(s.dayMicro)+BigInt(micro));
 s.totalMicro=String(BigInt(s.totalMicro)+BigInt(micro));
 s.calls=(Number(s.calls)||0)+1;
 s.lastAt=new Date().toISOString();
 return writeSpend(s);
}
// The gateway confirmed a signed payment was not charged: give it back (never below zero).
export function creditSpend(micro){
 const s=readSpend(),m=BigInt(micro),max=(a)=>a<0n?0n:a;
 s.dayMicro=String(max(BigInt(s.dayMicro)-m));
 s.totalMicro=String(max(BigInt(s.totalMicro)-m));
 s.calls=Math.max(0,(Number(s.calls)||0)-1);
 return writeSpend(s);
}

// ---- settings from plugin config / env ----
// A cap that is set but unreadable stops the proxy: it never falls back to a higher default.
const usd=(v,def,name)=>{
 if(v===undefined||v===null||v==="")return def;
 const n=Number(v);
 if(!Number.isFinite(n)||n<=0||n>1000)throw Error(name+" must be a number of USD above 0 (got "+String(v).slice(0,20)+")");
 return n;
};
const toMicro=(x)=>BigInt(Math.round(x*1e6));
export function settings(cfg={}){
 const gateway=String(cfg.gateway||process.env.MODEL_ACCESS_GATEWAY||DEFAULT_GATEWAY).replace(/\/+$/,"");
 const u=new URL(gateway);
 const local=u.hostname==="127.0.0.1"||u.hostname==="localhost"||u.hostname==="[::1]";
 if(u.protocol!=="https:"&&!(local&&u.protocol==="http:"))throw Error("gateway must be an https URL");
 const payTo=String(cfg.payTo||process.env.MODEL_ACCESS_PAY_TO||DEFAULT_PAY_TO);
 if(!/^0x[0-9a-fA-F]{40}$/.test(payTo))throw Error("payTo must be an EVM address");
 const port=Number(cfg.port||process.env.MODEL_ACCESS_PORT)||DEFAULT_PORT;
 if(!Number.isInteger(port)||port<1024||port>65535)throw Error("port must be 1024..65535");
 const perCall=usd(cfg.maxPerCallUsd??process.env.MODEL_ACCESS_MAX_PER_CALL_USD,DEFAULT_MAX_PER_CALL_USD,"maxPerCallUsd");
 const perDay=usd(cfg.maxPerDayUsd??process.env.MODEL_ACCESS_MAX_PER_DAY_USD,DEFAULT_MAX_PER_DAY_USD,"maxPerDayUsd");
 const contextTokens=Number(cfg.contextTokens)||60000;
 return {gateway,payTo,port,maxPerCallMicro:toMicro(perCall),maxPerDayMicro:toMicro(perDay),
  contextTokens:Math.min(Math.max(contextTokens,8000),90000)};
}


// The plugin's own config block in openclaw.json (plugins.entries.<id>.config), for the CLI. JSON5 files that
// plain JSON cannot read give {} (the CLI then says so).
export function readPluginConfig(){
 try{
  const c=JSON.parse(readFileSync(openclawConfigFile(),"utf8"));
  const cfg=c?.plugins?.entries?.[PLUGIN_ID]?.config;
  return cfg&&typeof cfg==="object"&&!Array.isArray(cfg)?cfg:{};
 }catch{return {};}
}
